insert into jj_collect.catalog(id,data) values('nu-563','{"id": "nu-563", "number": 563, "name_es": "Jesús · el aliado de la noche", "name_en": "Jesús · The Night’s Ally", "character": "jesus", "theme": "fantasia", "tags": ["my-name"], "rarity": 2, "sell": 80, "scrap": 12, "craft": 70, "dedication_es": "Quise que esta versión guardara una intención sencilla: acompañar sin apresurar.", "dedication_en": "I wanted this version to hold a simple intention: keeping company without rushing.", "art": 22, "collection": "decimonoveno-universo"}'::jsonb) on conflict(id) do nothing;
